			in := baseApply()
			in.RequestID = "dup1"
			_, dups[i] = w.Apply(in)
		}()
	}
	wg3.Wait()
	for _, err := range dups {
		if err != nil {
			t.Fatalf("duplicate apply should be idempotent: %v", err)
		}
	}
