func TestConcurrentApproveReject(t *testing.T) {
	w, _ := setupApproval(t)
	if _, err := w.Apply(approvalApply()); err != nil {
		t.Fatal(err)
	}

	var wg sync.WaitGroup
	results := make([]RequestView, 8)
	errs := make([]error, 8)
	for i := 0; i < 8; i++ {
		i := i
		wg.Add(1)
		go func() {
			defer wg.Done()
			if i%2 == 0 {
				results[i], errs[i] = w.Approve("u1", "r1", "sa", "dev-approve")
			} else {
				results[i], errs[i] = w.Reject("u1", "r1", "sa", "dev-approve", "concurrent reject")
			}
		}()
	}
	wg.Wait()

	approved, rejected := 0, 0
	for i, err := range errs {
		switch {
		case err == nil:
			if results[i].State == RequestReserved {
				approved++
			} else if results[i].State == RequestRejected {
				rejected++
			}
		case errors.Is(err, ErrRequestNotPending):
			// 竞争失败：状态已被对方决定。
		default:
			t.Fatalf("unexpected race err: %v", err)
		}
	}
	// 有且仅有一个成功决定。
	if approved+rejected != 1 {
		t.Fatalf("decisions = %d (approve %d reject %d), want exactly 1", approved+rejected, approved, rejected)
	}
	req, _ := w.Request("u1", "r1")
	if (req.State == RequestReserved) != (approved == 1) {
		t.Fatalf("final state = %v but approved count = %d", req.State, approved)
	}
	// 余额与状态一致：批准则预留 20，拒绝则不动。
	bal, _ := w.Balance("payer")
	if req.State == RequestReserved {
		if bal != (Balances{Available: 80, Reserved: 20}) {
			t.Fatalf("balance = %+v, want {80 20}", bal)
		}
	} else {
		if bal != (Balances{Available: 100, Reserved: 0}) {
			t.Fatalf("balance = %+v, want untouched", bal)
		}
	}
}

func TestConcurrentCancelApprove(t *testing.T) {
	w, _ := setupApproval(t)
	if _, err := w.Apply(approvalApply()); err != nil {
		t.Fatal(err)
	}

	var wg sync.WaitGroup
	wg.Add(2)
	var cancelView, approveView RequestView
	var cancelErr, approveErr error
	go func() { defer wg.Done(); cancelView, cancelErr = w.Cancel("u1", "r1") }()
	go func() { defer wg.Done(); approveView, approveErr = w.Approve("u1", "r1", "sa", "dev-approve") }()
	wg.Wait()

	req, _ := w.Request("u1", "r1")
	bal, _ := w.Balance("payer")
	switch req.State {
	case RequestCancelled:
		// 取消先完成：批准失败，余额不动。
		if approveErr == nil || !errors.Is(approveErr, ErrRequestNotPending) {
			t.Fatalf("approve after cancel err = %v, want ErrRequestNotPending", approveErr)
		}
		if cancelErr != nil {
			t.Fatalf("cancel err = %v", cancelErr)
		}
		if bal != (Balances{Available: 100, Reserved: 0}) {
			t.Fatalf("balance = %+v, want untouched", bal)
		}
	case RequestReserved:
		// 批准先完成：取消按已预留规则退回。
		if cancelErr != nil {
			t.Fatalf("cancel after approve err = %v", cancelErr)
		}
		if approveErr != nil {
			t.Fatalf("approve err = %v", approveErr)
		}
		if bal != (Balances{Available: 100, Reserved: 0}) {
			t.Fatalf("balance = %+v, want full refund {100 0}", bal)
		}
	default:
		t.Fatalf("unexpected final state = %v", req.State)
	}
	_ = cancelView
	_ = approveView
}

func TestPendingDoesNotOccupySharedQuota(t *testing.T) {
	w, _ := setupApproval(t)
	// 多笔待审批不占用共享累计额度：直接预留仍可进行。
	for i := 0; i < 3; i++ {
		in := approvalApply()
		in.RequestID = fmt.Sprintf("p%d", i)
		if _, err := w.Apply(in); err != nil {
			t.Fatal(err)
		}
	}
	pv, _ := w.Policy("p-approval")
	if pv.ReservedTotal != 0 {
		t.Fatalf("pending occupies quota: reserved %d", pv.ReservedTotal)
	}
	// 直接预留一笔 30（累计上限 50）不受待审批影响。
	reserved := approvalApply()
	reserved.RequestID = "r-direct"
	reserved.EstimatedFee = 30
	if _, err := w.Apply(reserved); err != nil {
		t.Fatal(err)
	}
	pv, _ = w.Policy("p-approval")
	if pv.ReservedTotal != 30 {
		t.Fatalf("reserved total = %d, want 30", pv.ReservedTotal)
	}
}

