func TestApproveQuotaRecheck(t *testing.T) {
	w, c := setupApproval(t)
	// 另建一条门槛 25 的策略：费用等于 25 直接预留，20 进入待审批，
	// 累计上限 50，便于构造“批准时共享额度不足”。
	p := approvalPolicy(c)
	p.ID = "p-quota"
	p.ApprovalThreshold = 25
	if err := w.SavePolicy(p); err != nil {
		t.Fatal(err)
	}
	apply := func(rid string, fee int64) RequestView {
		in := approvalApply()
		in.PolicyID = "p-quota"
		in.RequestID = rid
		in.EstimatedFee = fee
		req, err := w.Apply(in)
		if err != nil {
			t.Fatal(err)
		}
		return req
	}

	// 第一笔 25 直接预留，占用累计额度 25。
	if r := apply("r-res", 25); r.State != RequestReserved {
		t.Fatalf("fee 25 state = %v, want reserved", r.State)
	}
	// 第二笔 20 进入待审批；批准时 25+20=45 <= 50，应成功。
	if r := apply("r1", 20); r.State != RequestPendingApproval {
		t.Fatalf("fee 20 state = %v, want pending", r.State)
	}
	if _, err := w.Approve("u1", "r1", "sa", "dev-approve"); err != nil {
		t.Fatalf("approve within remaining quota: %v", err)
	}
	pv, _ := w.Policy("p-quota")
	if pv.ReservedTotal != 45 {
		t.Fatalf("reserved total = %d, want 45", pv.ReservedTotal)
	}

	// 第三笔 20 待审批；批准时 45+20=65 > 50，拒绝批准并保留待审批。
	if r := apply("r3", 20); r.State != RequestPendingApproval {
		t.Fatalf("fee 20 state = %v, want pending", r.State)
	}
	if _, err := w.Approve("u1", "r3", "sa", "dev-approve"); !errors.Is(err, ErrQuotaExceeded) {
		t.Fatalf("err = %v, want ErrQuotaExceeded", err)
	}
	req, _ := w.Request("u1", "r3")
	if req.State != RequestPendingApproval {
		t.Fatalf("state = %v, want still pending", req.State)
	}
	// 取消第一笔释放额度后，第三笔可批准。
	if _, err := w.Cancel("u1", "r-res"); err != nil {
		t.Fatal(err)
	}
	if _, err := w.Approve("u1", "r3", "sa", "dev-approve"); err != nil {
		t.Fatalf("approve after quota freed: %v", err)
	}
}

